/bin/bash -lc "python - <<'PY'
import json
x=json.load(open('judge-input.json'))['finalCanvas']
for d in x['diagrams']:
 lines=d['ascii'].splitlines()
 print(d['id'],d['position'],'lines',len(lines),'width',max(map(len,lines)))
 for i,s in enumerate(lines,1): print(f'{i}: {s}')
print('EDGE ENDPOINTS, 1-BASED')
by={d['id']:d['ascii'].splitlines() for d in x['diagrams']}
for e in x['edges']:
 print(e['label'])
 for side in ['source','target']:
  a=e[side]; print(side,a,by[a['diagram']][a['line']-1])
PY"

